#include "hwio/stepper.hpp"
#include "hwio/actuator_repository.hpp"
#include <Windows.h>
#include <condition_variable>
#include <filesystem>
#include <fstream>
#include <iomanip>
#include <sstream>
#include <thread>
namespace hwio {
bool stepper_definition_valid(const StepperDefinition& d,bool motion,std::string& error){
    const auto& a=d.address;if(d.name.size()>128 || a.provider!="phidget22" || a.device.size()>1024 || (a.assigned() && (a.serial<=0 || a.hub_port<0 || a.channel<0 || a.channel>65535 || (a.model && a.model!=0x95))) || a.server.size()>253 || a.server.find_first_of("\r\n\t /\\")!=a.server.npos || a.port==0 || a.port>65535 || (a.remote && a.server.empty())){error="Enter an exact STC1005 VINT address";return false;}
    for(const auto v:{d.current,d.holding_current,d.velocity,d.acceleration,d.full_steps,d.gearing,d.kp,d.ki,d.kd,d.vff,d.aff,d.feedback_velocity,d.feedback_acceleration,d.backlash})if(!std::isfinite(v) || v<0){error="Stepper settings must be finite and non-negative";return false;}
    if(d.interval_ms<1 || d.interval_ms>60000 || d.failsafe_ms<1 || d.failsafe_ms>60000 || d.feedback.input_profile.size()>65536 || d.gearing<=0 || !std::isfinite(d.output_counts())){error="Invalid stepper interval, gearing or feedback";return false;}
    if(motion && (!a.assigned() || d.current<=0 || d.holding_current>d.current || d.velocity<=0 || d.acceleration<=0 || (d.run_mode && (d.feedback.kind!=MotorPositionSource::analogue || d.feedback.input_profile.empty() || d.feedback_velocity<=0 || d.feedback_acceleration<=0)))){error="Set current, holding current, velocity and acceleration; RUN needs measured feedback and position-loop limits";return false;}
    error.clear();return true;
}
bool load_stepper_settings(const std::wstring& dir,std::array<StepperDefinition,stepper_slots>& defs,std::string& error){
    try{auto parsed=defs;for(unsigned n=0;n<stepper_slots;++n){parsed[n]={};parsed[n].name="Stepper "+std::to_string(n);}const auto path=std::filesystem::path(dir)/L"stepper-settings.cfg";if(!std::filesystem::exists(path)){defs=parsed;error.clear();return true;}if(std::filesystem::file_size(path)>262144)throw std::runtime_error("Stepper settings exceed 256 KiB");std::ifstream in(path,std::ios::binary);std::string header;std::getline(in,header);if(!header.empty() && header.back()=='\r')header.pop_back();if(header!="[hwio-stepper-settings-v1]")throw std::runtime_error("Invalid stepper-settings.cfg version");
        for(unsigned n=0;n<stepper_slots;++n){auto& d=parsed[n];auto& a=d.address;unsigned slot{};if(!(in>>slot>>std::quoted(d.name)>>std::quoted(a.device)>>a.serial>>a.hub_port>>a.channel>>a.model>>a.remote>>std::quoted(a.server)>>a.port>>d.run_mode>>d.current>>d.holding_current>>d.velocity>>d.acceleration>>d.full_steps>>d.gearing>>d.kp>>d.ki>>d.kd>>d.vff>>d.aff>>d.feedback_velocity>>d.feedback_acceleration>>d.backlash>>d.interval_ms>>d.failsafe_ms>>std::quoted(d.feedback.input_profile)>>d.feedback.inverted) || slot!=n)throw std::runtime_error("Invalid stepper settings row");d.feedback.kind=d.feedback.input_profile.empty()?MotorPositionSource::none:MotorPositionSource::analogue;if(!stepper_definition_valid(d,false,error))return false;for(unsigned j=0;j<n;++j)if(a.same_physical(parsed[j].address))throw std::runtime_error("Duplicate stepper device ownership");}
        in>>std::ws;if(!in.eof())throw std::runtime_error("Unexpected stepper settings data");defs=std::move(parsed);error.clear();return true;
    }catch(const std::exception& e){error=e.what();return false;}
}
bool save_stepper_settings(const std::wstring& dir,const std::array<StepperDefinition,stepper_slots>& defs,std::string& error){
    std::ostringstream out;out<<"[hwio-stepper-settings-v1]\n"<<std::setprecision(17);for(unsigned n=0;n<stepper_slots;++n){const auto& d=defs[n];const auto& a=d.address;if(!stepper_definition_valid(d,false,error))return false;for(unsigned j=0;j<n;++j)if(a.same_physical(defs[j].address)){error="Duplicate stepper ownership";return false;}
        out<<n<<' '<<std::quoted(d.name)<<' '<<std::quoted(a.device)<<' '<<a.serial<<' '<<a.hub_port<<' '<<a.channel<<' '<<a.model<<' '<<a.remote<<' '<<std::quoted(a.server)<<' '<<a.port<<' '<<d.run_mode<<' '<<d.current<<' '<<d.holding_current<<' '<<d.velocity<<' '<<d.acceleration<<' '<<d.full_steps<<' '<<d.gearing<<' '<<d.kp<<' '<<d.ki<<' '<<d.kd<<' '<<d.vff<<' '<<d.aff<<' '<<d.feedback_velocity<<' '<<d.feedback_acceleration<<' '<<d.backlash<<' '<<d.interval_ms<<' '<<d.failsafe_ms<<' '<<std::quoted(d.feedback.input_profile)<<' '<<d.feedback.inverted<<'\n';}
    if(out.str().size()>262144){error="Stepper settings exceed 256 KiB";return false;}return actuator_atomic_write((std::filesystem::path(dir)/L"stepper-settings.cfg").wstring(),out.str(),error);
}
namespace {
MotorParameters parameters(const StepperDefinition& d){MotorParameters p;p.current_limit=d.current;p.velocity_limit=d.run_mode?d.feedback_velocity:d.velocity;p.acceleration=d.run_mode?d.feedback_acceleration:d.acceleration;p.kp=d.kp;p.ki=d.ki;p.kd=d.kd;p.vff=d.vff;p.aff=d.aff;p.backlash=d.run_mode?d.backlash:0;p.numeric_range_only=true;p.minimum=-9e12;p.maximum=9e12;p.feedback_interval_ms=d.interval_ms;p.failsafe_ms=d.failsafe_ms;p.rescale=1;p.units=d.run_mode?"raw sensor counts":"microsteps";return p;}
}
struct Steppers::Impl {
    struct Slot {StepperView view;std::shared_ptr<PositionMotorBackend> backend,retiring;MotorCommandResult retirement;bool inspect{},changed{},hold{},release{},operator_stopped{};std::optional<StepperDefinition> saving;std::uint64_t drive_until{};int drive{};MotorCommandResult operation;unsigned stage{};double manual_target{};};
    std::array<Slot,stepper_slots> slots;std::wstring directory;Factory factory;mutable std::mutex mutex;std::condition_variable wake;std::thread worker;bool quit{},enabled{};std::uint64_t revision{1};int selected{-1};std::string storage_error;
    void tick(Slot& s){auto& v=s.view;
        if(s.changed && !s.retiring){if(s.backend){s.retiring=std::move(s.backend);s.retirement=s.retiring->close();}s.changed=false;s.stage=0;s.operation={};s.drive=0;}
        if(s.retiring){const auto result=s.retirement.id?s.retiring->result(s.retirement.id):std::optional(s.retirement);if(!result || result->stage==MotorResultStage::queued)return;if(!*result){v.status="Previous stepper release unconfirmed: "+result->reason;return;}s.retiring.reset();if(s.changed)return;}
        if(s.release){if(s.backend)s.backend->disengage();s.release=false;s.drive=0;}
        if(s.hold){if(s.backend)s.backend->stop();s.hold=false;s.drive=0;}
        if(s.inspect && enabled && v.draft.address.assigned() && !s.backend){s.backend=factory(v.draft);s.backend->feedback(v.draft.feedback);s.operation=s.backend->inspect();s.stage=1;s.inspect=false;}
        if(s.backend){v.live=s.backend->snapshot();if(s.operation.id){const auto r=s.backend->result(s.operation.id);if(r && r->stage!=MotorResultStage::queued){s.operation={};if(!*r){v.status=r->reason;s.stage=0;s.drive=0;}else if(s.stage==1){std::string reason;if(stepper_definition_valid(v.draft,true,reason)){s.operation=s.backend->configure(hwio::parameters(v.draft));s.stage=2;v.status="Configuring disengaged";}else{s.stage=0;v.status="Connected; "+reason;}}else if(s.stage==4 && !v.live.engaged){s.operation=s.backend->engage();s.stage=3;v.status="Engaging selected target";}else if(s.stage==5){s.operation=s.backend->target(s.manual_target);s.stage=3;v.status="Moving to selected position";}else if(s.stage==6 && v.bench){s.operation=s.backend->reference(0,v.live.capabilities.minimum_position,v.live.capabilities.maximum_position);s.stage=3;v.status="Zeroing the count while disengaged";}else{s.stage=0;v.status="Command accepted";}}}
            if(!v.live.fault.empty()){s.drive=0;v.status=v.live.fault;}
            if(s.drive && GetTickCount64()>=s.drive_until){s.backend->stop();s.drive=0;}
            if(s.drive && v.bench && enabled && v.live.configured && !s.operation.id){if(!v.live.engaged && !s.backend->target_before_engage()){s.operation=s.backend->engage();s.stage=3;return;}s.backend->jog(s.drive*.2*(v.draft.run_mode?v.draft.feedback_velocity:v.draft.velocity));s.backend->renew();v.status="Manual motion";}
        }
    }
    void run(){std::unique_lock lock(mutex);while(!quit){wake.wait_for(lock,std::chrono::milliseconds(50));for(unsigned n=0;n<stepper_slots;++n){auto& s=slots[n];try{
            // Remote teardown and durable writes must never hold the UI snapshot mutex.
            tick(s);if(s.saving){const auto definition=*s.saving;s.saving.reset();std::array<StepperDefinition,stepper_slots> saved;for(unsigned j=0;j<stepper_slots;++j)saved[j]=slots[j].view.saved;saved[n]=definition;std::string error;lock.unlock();const bool committed=save_stepper_settings(directory,saved,error);lock.lock();if(committed){s.view.saved=definition;s.view.dirty=s.view.saved!=s.view.draft;s.view.status="Settings saved";}else s.view.status="Unsaved: "+error;}
        }catch(const std::exception& e){if(!lock.owns_lock())lock.lock();if(s.backend)s.backend->disengage();s.drive=0;s.view.status=e.what();}}}
        std::array<std::shared_ptr<PositionMotorBackend>,stepper_slots> retired;for(unsigned n=0;n<stepper_slots;++n)retired[n]=std::move(slots[n].backend);lock.unlock();for(auto& backend:retired)if(backend)backend->close();
    }
};
Steppers::Steppers(std::wstring dir,Factory factory):impl_(std::make_unique<Impl>()){impl_->directory=std::move(dir);impl_->factory=std::move(factory);std::array<StepperDefinition,stepper_slots> d;if(!load_stepper_settings(impl_->directory,d,impl_->storage_error))for(unsigned n=0;n<stepper_slots;++n)d[n].name="Stepper "+std::to_string(n);for(unsigned n=0;n<stepper_slots;++n){impl_->slots[n].view.draft=impl_->slots[n].view.saved=d[n];impl_->slots[n].view.status=impl_->storage_error.empty()?"Unassigned / stopped":impl_->storage_error;}impl_->worker=std::thread([this]{impl_->run();});}
Steppers::~Steppers(){close();}
StepperView Steppers::snapshot(unsigned n)const{std::lock_guard lock(impl_->mutex);auto v=n<stepper_slots?impl_->slots[n].view:StepperView{};if(n<stepper_slots && impl_->slots[n].backend)v.live=impl_->slots[n].backend->snapshot();return v;}
bool Steppers::edit(unsigned n,StepperDefinition d,std::string& error){if(n>=stepper_slots || !stepper_definition_valid(d,false,error))return false;std::lock_guard lock(impl_->mutex);if(!impl_->storage_error.empty()){error=impl_->storage_error;return false;}for(unsigned j=0;j<stepper_slots;++j)if(j!=n && d.address.same_physical(impl_->slots[j].view.draft.address)){error="Stepper device already assigned";return false;}auto& s=impl_->slots[n];if(s.view.draft==d)return true;s.view.draft=std::move(d);s.view.dirty=s.view.draft!=s.view.saved;s.changed=true;s.inspect=false;s.drive=0;++impl_->revision;impl_->wake.notify_one();error.clear();return true;}
bool Steppers::save(unsigned n,std::string& error){std::lock_guard lock(impl_->mutex);if(n>=stepper_slots || impl_->quit){error="Stepper save unavailable";return false;}impl_->slots[n].saving=impl_->slots[n].view.draft;impl_->wake.notify_one();error.clear();return true;}
void Steppers::revert(unsigned n){if(n>=stepper_slots)return;stop(n);std::lock_guard lock(impl_->mutex);auto& s=impl_->slots[n];s.view.draft=s.view.saved;s.view.dirty=false;s.changed=true;++impl_->revision;}
void Steppers::clear(unsigned n){auto d=snapshot(n).draft;d.address={};std::string error;(void)edit(n,d,error);}
void Steppers::inspect(unsigned n){std::lock_guard lock(impl_->mutex);if(n<stepper_slots){auto& s=impl_->slots[n];s.inspect=true;if(s.backend)s.changed=true;impl_->wake.notify_one();}}
void Steppers::bench(int n){std::lock_guard lock(impl_->mutex);for(unsigned j=0;j<stepper_slots;++j){auto& s=impl_->slots[j];if(s.view.bench && int(j)!=n){s.drive=0;s.operation={};s.stage=0;s.operator_stopped=true;s.release=!s.backend;if(s.backend)s.backend->disengage();}s.view.bench=int(j)==n;}impl_->selected=n;impl_->wake.notify_one();}
void Steppers::drive(unsigned n,int direction,bool begin){std::lock_guard lock(impl_->mutex);if(n<stepper_slots && impl_->slots[n].view.bench && impl_->enabled){auto& s=impl_->slots[n];if(s.operator_stopped && !begin)return;if(begin)s.operator_stopped=false;s.drive=direction;s.drive_until=GetTickCount64()+250;s.inspect=true;impl_->wake.notify_one();}}
void Steppers::hold(unsigned n){std::lock_guard lock(impl_->mutex);if(n<stepper_slots){auto& s=impl_->slots[n];s.drive=0;s.operation={};s.stage=0;s.hold=!s.backend;if(s.backend)s.backend->stop();impl_->wake.notify_one();}}
void Steppers::stop(unsigned n){std::lock_guard lock(impl_->mutex);if(n<stepper_slots){auto& s=impl_->slots[n];s.drive=0;s.operator_stopped=true;s.release=!s.backend;s.operation={};s.stage=0;if(s.backend)s.backend->disengage();s.view.status="Drive release requested";impl_->wake.notify_one();}}
bool Steppers::move_to(unsigned n,double target,std::string& error){std::lock_guard lock(impl_->mutex);if(n>=stepper_slots || !impl_->enabled || !std::isfinite(target)){error="Enter a finite position with Phidgets enabled";return false;}auto& s=impl_->slots[n];if(!s.view.bench || !s.backend || !s.backend->snapshot().configured || s.operation.id || s.changed || s.retiring){error="Open/configure this motor on its manual page first";return false;}const auto live=s.backend->snapshot();if(target<live.capabilities.minimum_position || target>live.capabilities.maximum_position){error="Target outside controller numeric range";return false;}s.drive=0;s.operator_stopped=false;s.manual_target=target;if(s.backend->target_before_engage()){s.operation=s.backend->target(target);s.stage=4;}else if(!live.engaged){s.operation=s.backend->engage();s.stage=5;}else{s.operation=s.backend->target(target);s.stage=3;}s.view.status="Moving to selected position";impl_->wake.notify_one();error.clear();return true;}
bool Steppers::zero(unsigned n,std::string& error){std::lock_guard lock(impl_->mutex);if(n>=stepper_slots || !impl_->enabled){error="Phidgets support is disabled";return false;}auto& s=impl_->slots[n];if(!s.view.bench || !s.backend || !s.backend->snapshot().configured || s.changed || s.retiring){error="Open/configure this motor on its manual page first";return false;}s.drive=0;s.operator_stopped=true;s.operation=s.backend->disengage();s.stage=6;s.view.status="Releasing drive and zeroing the count";impl_->wake.notify_one();error.clear();return true;}
void Steppers::provider_enabled(bool on){std::lock_guard lock(impl_->mutex);if(impl_->enabled==on)return;impl_->enabled=on;if(!on)for(auto& s:impl_->slots){s.drive=0;s.changed=true;s.release=true;if(s.backend)s.backend->disengage();}impl_->wake.notify_one();}
std::shared_ptr<PositionMotorBackend> Steppers::acquire(unsigned n,std::string& error){std::lock_guard lock(impl_->mutex);if(n>=stepper_slots || !impl_->enabled){error="Stepper provider unavailable";return {};}auto& s=impl_->slots[n];if(s.view.bench){error="Stepper page owns manual control";return {};}if(!stepper_definition_valid(s.view.draft,true,error))return {};if(s.backend && !s.backend->snapshot().fault.empty())s.changed=true;if(!s.backend || s.changed){s.inspect=true;impl_->wake.notify_one();error="Opening disengaged";return {};}error.clear();return s.backend;}
MotorParameters Steppers::parameters(unsigned n)const{return hwio::parameters(snapshot(n).draft);}
std::array<MotorFeedbackDefinition,stepper_slots> Steppers::feedback_definitions()const{std::lock_guard lock(impl_->mutex);std::array<MotorFeedbackDefinition,stepper_slots> result;for(unsigned n=0;n<stepper_slots;++n)result[n]=impl_->slots[n].view.draft.feedback;return result;}
std::uint64_t Steppers::revision()const{std::lock_guard lock(impl_->mutex);return impl_->revision;}
std::array<StepperDefinition,stepper_slots> Steppers::saved()const{std::lock_guard lock(impl_->mutex);std::array<StepperDefinition,stepper_slots> d;for(unsigned n=0;n<stepper_slots;++n)d[n]=impl_->slots[n].view.saved;return d;}
void Steppers::close(){if(!impl_ || !impl_->worker.joinable())return;{std::lock_guard lock(impl_->mutex);impl_->quit=true;impl_->wake.notify_one();}impl_->worker.join();}
}
